using Microsoft.EntityFrameworkCore;
using MobiStore.Core;

namespace MobiStore.Server;
public static class WebPages
{
    public static void MapWebPages(this WebApplication app)
    {
        app.MapGet("/catalog", () => Results.Content(Catalog, "text/html; charset=utf-8"));
        app.MapGet("/mobile", () => Results.Content(Mobile, "text/html; charset=utf-8"));
        app.MapGet("/api/public/catalog", async (StoreDb db) =>
        {
            var products = await db.Products.AsNoTracking().Where(x => x.Published).OrderBy(x => x.Name).ToListAsync();
            var result = new List<object>();
            foreach (var p in products)
            {
                var detail = await StoreExtensions.Read<ProductDetails>(db, "product:" + p.Id.ToString("N"));
                result.Add(new { p.Id, p.Code, p.Name, Price = p.RetailPrice, detail?.Brand, detail?.Models, detail?.Color, detail?.ImageUrl });
            }
            var company = await db.Companies.AsNoTracking().SingleOrDefaultAsync();
            return new { shop = company?.Name ?? "موبي ستور", currency = company?.BaseCurrency ?? "USD", products = result };
        });
    }
    private const string Mobile = """
    <!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#11233e"><meta name="apple-mobile-web-app-capable" content="yes"><title>موبي ستور — متابعة الأعمال</title>
    <style>*{box-sizing:border-box}body{margin:0;background:#eff3f8;color:#172b46;font:16px 'Segoe UI',Tahoma,sans-serif}header{background:#11233e;color:white;padding:25px}header small{color:#65dfc0}h1{font-size:25px}main{max-width:900px;margin:auto;padding:20px}.card{background:white;border-radius:16px;padding:22px;margin-bottom:18px}input,select,button{font:inherit;padding:13px;border-radius:9px;border:1px solid #dae4ed;width:100%;margin:7px 0}button{background:#078b78;color:white;border:0;cursor:pointer}button:disabled{opacity:.45}.nav{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}label{display:block;font-size:13px;color:#657e95;margin-top:10px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:12px 7px;border-bottom:1px solid #edf1f6;text-align:right}.scroll{overflow:auto}#status{padding:14px;color:#078b78;white-space:pre-wrap}.row{border:1px solid #e3eaf1;padding:16px;border-radius:10px;margin:10px 0}.muted{font-size:13px;color:#7d90a6}a{color:#078b78}</style>
    <header><small>MOBI STORE</small><h1>متابعة أعمال المحل</h1><div id="identity"></div></header><main><div id="status" role="status"></div>
    <form id="login" class="card"><h2>تسجيل الدخول</h2><label>قاعدة البيانات</label><select id="database"></select><label>اسم المستخدم</label><input id="username" autocomplete="username" required><label>كلمة المرور</label><input id="password" type="password" autocomplete="current-password" required><button>دخول</button></form>
    <section id="workspace" hidden><div class="card nav"><button id="overview">المؤشرات</button><button id="accounts">العملاء</button><button id="invoices">الفواتير</button><button id="due">الاستحقاقات</button><button id="collection">قبض دفعة</button><button id="logout">خروج</button></div><div id="body" class="card"></div></section></main>
    <script>
    let token='',session=null,company=null,pending=null,locked=false;const $=id=>document.getElementById(id),el=(tag,text)=>{let x=document.createElement(tag);if(text!==undefined)x.textContent=text;return x};function status(x){$('status').textContent=x}function clear(title){let b=$('body');b.replaceChildren(el('h2',title));return b}function table(root,rows,cols){let wrap=el('div'),t=el('table'),tr=el('tr');wrap.className='scroll';for(let c of cols)tr.append(el('th',c[0]));t.append(tr);for(let row of rows){let tr=el('tr');for(let c of cols)tr.append(el('td',row[c[1]]??''));t.append(tr)}wrap.append(t);root.append(wrap)}async function api(path,method='GET',payload){let r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-MobiStore-Database':$('database').value,...token?{Authorization:'Bearer '+token}:{}},body:payload===undefined?undefined:JSON.stringify(payload)});if(!r.ok){let x=await r.json().catch(()=>({}));let error=Error(x.error||(r.status===401?'انتهت الجلسة. سجل الدخول مجددًا.':'تعذر تنفيذ الطلب'));error.status=r.status;throw error}if(r.status===204)return null;return r.json()}async function run(fn){if(locked)return;locked=true;document.querySelectorAll('button').forEach(x=>x.disabled=true);try{status('جارٍ التحميل…');await fn();status('')}catch(e){status(e.message)}finally{locked=false;document.querySelectorAll('button').forEach(x=>x.disabled=false);if(session&&!session.isAdmin)$('collection').disabled=true;if(pending)document.querySelectorAll('.nav button').forEach(x=>x.disabled=true)}}
    fetch('/api/databases').then(x=>x.json()).then(rows=>rows.forEach(p=>{let o=el('option',p.title);o.value=p.name;$('database').append(o)})).then(()=>{let name=new URLSearchParams(location.search).get('database');if(name&&[...$('database').options].some(o=>o.value===name))$('database').value=name}).catch(()=>status('تعذر الاتصال بالخادم'));
    $('login').onsubmit=e=>{e.preventDefault();run(async()=>{let r=await api('login','POST',{username:$('username').value,password:$('password').value});$('password').value='';token=r.token;let s=await api('session');session=s.user;company=s.company;$('identity').textContent=company.shopName+' · '+session.displayName;$('login').hidden=true;$('workspace').hidden=false;if(session.isAdmin||session.permissions.includes('accounts.view'))await overview();else clear('مرحبًا '+session.displayName)})};
    async function overview(){let d=await api('dashboard'),b=clear('نظرة عامة');for(let [label,key]of [['مبيعات اليوم','salesToday'],['أرصدة العملاء','customerDebt'],['الصندوق الرئيسي','cashBase'],['صناديق مفتوحة','openSessions']]){let row=el('div',label+': '+d[key]+(key==='openSessions'?'':' '+d.baseCurrency));row.className='row';b.append(row)}}$('overview').onclick=()=>run(overview);
    $('accounts').onclick=()=>run(async()=>{let rows=await api('customers'),b=clear('حسابات العملاء');let search=el('input');search.placeholder='بحث عن عميل';let list=el('div');b.append(search,list);function render(){list.replaceChildren();for(let c of rows.filter(c=>c.name.includes(search.value))){let row=el('div');row.className='row';row.append(el('strong',c.name),el('p','الرصيد: '+(c.balance??'غير متاح')+' '+company.baseCurrency));let button=el('button','كشف الحساب');button.onclick=()=>run(async()=>{let ledger=await api('customers/'+c.id+'/ledger');table(clear('كشف حساب — '+c.name),ledger,[['السند','number'],['التاريخ','createdUtc'],['مدين','debit'],['دائن','credit'],['الرصيد','balance']])});row.append(button);list.append(row)}}search.oninput=render;render()});
    $('invoices').onclick=()=>run(async()=>{let rows=await api('invoices');table(clear('الفواتير'),rows,[['رقم','number'],['العميل','customer'],['الموظف','seller'],['المجموع','total'],['العملة','currency'],['الدفعة بالأساس','paidBase']])});$('due').onclick=()=>run(async()=>table(clear('استحقاقات العملاء'),await api('due'),[['العميل','customer'],['الفاتورة','number'],['المتبقي','remaining'],['الاستحقاق','dueDate']]));
    $('collection').onclick=()=>run(async()=>{if(!session.isAdmin)throw Error('التحصيل للمدير فقط');let b=clear('قبض دفعة من العميل'),customers=await api('customers'),sessions=await api('sessions'),mine=sessions.find(x=>x.userId===session.userId);if(!mine){let open=el('button','فتح صندوق باسمي');open.onclick=()=>run(async()=>{await api('sessions/open','POST',{requestId:crypto.randomUUID()});status('تم فتح الصندوق. افتح قبض الدفعة للمتابعة.')});b.append(el('p','افتح صندوقك قبل القبض.'),open);return}let f=el('form'),customer=el('select'),amount=el('input'),currency=el('select'),rate=el('input'),notes=el('input');for(let c of customers){let o=el('option',c.name);o.value=c.id;customer.append(o)}for(let c of ['USD','SYP']){let o=el('option',c);o.value=c;currency.append(o)}currency.value=company.baseCurrency;amount.type=rate.type='number';amount.step=rate.step='0.0001';amount.min='0.0001';rate.min='0.0001';amount.required=rate.required=true;rate.value=(await api('exchange-rate')).rate;for(let [label,input]of [['العميل',customer],['المبلغ',amount],['العملة',currency],['ليرات لكل دولار',rate],['البيان',notes]])f.append(el('label',label),input);let save=el('button','تأكيد القبض وإصدار الإيصال');f.append(save);b.append(el('p','الصندوق: '+mine.owner),f);f.onsubmit=e=>{e.preventDefault();run(async()=>{pending??={requestId:crypto.randomUUID(),sessionId:mine.id,customerId:customer.value,currency:currency.value,amount:Number(amount.value),rate:Number(rate.value),notes:notes.value};f.querySelectorAll('input,select').forEach(x=>x.disabled=true);let result,receipt;try{result=await api('receipts','POST',pending)}catch(e){if(e.status>=400&&e.status<500&&![408,429].includes(e.status)){pending=null;f.querySelectorAll('input,select').forEach(x=>x.disabled=false)}throw e}receipt=await api('receipts/'+result.id);pending=null;let box=clear('إيصال قبض'),fields=[['الرقم',receipt.number],['العميل',receipt.customer],['المبلغ',receipt.amount+' '+receipt.currency],['سعر الصرف',receipt.rate],['الرصيد بعد القبض',receipt.balance+' '+receipt.baseCurrency],['المدير',receipt.manager],['التاريخ',receipt.createdUtc]];for(let [k,v]of fields)box.append(el('p',k+': '+v));let print=el('button','طباعة / حفظ PDF');print.onclick=()=>window.print();box.append(print);let style=el('style');style.textContent='@media print{header,.nav,#status{display:none}body{background:white}.card{border:0}button{display:none}}';box.append(style)})}});
    $('logout').onclick=()=>run(async()=>{try{await api('logout','POST',{})}finally{token='';session=null;pending=null;$('workspace').hidden=true;$('login').hidden=false;$('identity').textContent=''}});
    </script></html>
    """;
    private const string Catalog = """
    <!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>كتالوج موبي ستور</title>
    <style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172b46;font:16px 'Segoe UI',Tahoma,sans-serif}header{background:#11233e;color:white;padding:40px max(6vw,20px)}header small{color:#68dec3}h1{font-size:34px;margin:12px 0}header p{color:#a6bdd0}main{max-width:1250px;margin:auto;padding:30px 20px}input{width:100%;padding:17px;border:1px solid #dce5ef;border-radius:12px;font:inherit;margin-bottom:25px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:22px}article{background:white;border-radius:18px;overflow:hidden;border:1px solid #e1e8f1}.photo{height:205px;background:#e9f4ef;display:grid;place-items:center;color:#15856f;font-size:50px}img{width:100%;height:100%;object-fit:contain;background:white}.info{padding:22px}h2{font-size:19px;margin:0 0 10px}.meta{color:#798da4;line-height:1.8;font-size:14px}.price{color:#078b78;font-weight:bold;font-size:22px;margin-top:15px}footer{text-align:center;color:#7e91a8;padding:30px}</style>
    <header><small>MOBI STORE · كتالوج العرض</small><h1 id="shop">اكتشف ملحقاتك القادمة</h1><p>تصفّح المواد والصور والأسعار، وتواصل معنا للاستفسار.</p></header><main><input id="search" aria-label="بحث" placeholder="ابحث عن مادة أو ماركة أو موديل هاتف…"><div id="status">جارٍ تحميل الكتالوج…</div><div id="products" class="grid"></div></main><footer>كتالوج للعرض والاستفسار</footer>
    <script>let data;const node=(tag,text,cls)=>{let n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};function render(){let q=document.getElementById('search').value.trim().toLowerCase(),root=document.getElementById('products');root.replaceChildren();let rows=data.products.filter(p=>[p.name,p.code,p.brand,p.models,p.color].join(' ').toLowerCase().includes(q));document.getElementById('status').textContent=rows.length?'': 'لا توجد مواد منشورة مطابقة';for(let p of rows){let card=node('article'),photo=node('div','M','photo');try{if(!p.imageUrl)throw Error();let u=new URL(p.imageUrl,location.origin);if(u.protocol==='https:'||u.origin===location.origin){let img=node('img');img.src=u.href;img.alt=p.name;img.loading='lazy';img.referrerPolicy='no-referrer';photo.replaceChildren(img)}}catch{}let info=node('div','','info');info.append(node('h2',p.name),node('div',[p.brand,p.models,p.color].filter(Boolean).join(' · '),'meta'),node('div',new Intl.NumberFormat('ar',{maximumFractionDigits:4}).format(p.price)+' '+data.currency,'price'));card.append(photo,info);root.append(card)}}fetch('/api/public/catalog',{headers:{'X-MobiStore-Database':new URLSearchParams(location.search).get('database')||''}}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{data=x;document.getElementById('shop').textContent=x.shop;render()}).catch(()=>document.getElementById('status').textContent='تعذر تحميل الكتالوج. أعد المحاولة لاحقًا.');document.getElementById('search').oninput=()=>data&&render();</script></html>
    """;
